<!-- Hand-authored — NOT generated by prism, and prism will not overwrite it -->
<!-- (it only replaces files carrying its header). See the React wrapper for  -->
<!-- the reasoning: virtualization is the one case where the wrapper has to   -->
<!-- own the rows, because only Svelte can create a Svelte row. Rows come from-->
<!-- the `row` snippet, which is how Svelte 5 says "render this item".        -->
<script lang="ts">
  import '@arclux/arc-ui/virtual-list';
  import type { Snippet } from 'svelte';

  interface Props {
    /** The full data array. Only the visible slice is rendered. */
    items: unknown[];
    /** Renders one row. Called only for rows currently on screen. */
    row: Snippet<[unknown, number]>;
    /** Row height in pixels. Must match what actually renders. */
    itemHeight?: number;
    /** Rows rendered above and below the viewport, to cover fast scrolling. */
    overscan?: number;
    /** Called when the visible range changes. `end` is exclusive. */
    onrangechange?: (range: { start: number; end: number }) => void;
    class?: string;
    id?: string;
    style?: string;
    [key: `data-${string}`]: unknown;
    [key: `aria-${string}`]: unknown;
  }

  let {
    items,
    row,
    itemHeight = 40,
    overscan = 5,
    onrangechange,
    ...rest
  }: Props = $props();

  type ListElement = HTMLElement & {
    items?: unknown[];
    itemHeight?: number;
    visibleRange?: { start: number; end: number };
  };

  let el: ListElement | undefined = $state();
  let range = $state({ start: 0, end: 0 });

  // Both are set as properties: an array would stringify as an attribute, and
  // `itemHeight` lowercases to a name Lit ignores.
  $effect(() => {
    if (!el) return;
    el.items = items;
    el.itemHeight = itemHeight;
  });

  $effect(() => {
    const node = el;
    if (!node) return;
    const onRange = (e: Event) => {
      const { start, end } = (e as CustomEvent).detail;
      range = { start, end };
      onrangechange?.({ start, end });
    };
    node.addEventListener('arc-range-change', onRange);
    // The element may have measured before this ran, in which case its first
    // range event is already spent.
    if (node.visibleRange) range = { ...node.visibleRange };
    return () => node.removeEventListener('arc-range-change', onRange);
  });

  const visible = $derived(
    Array.from(
      { length: Math.max(0, Math.min(range.end, items.length) - range.start) },
      (_, i) => range.start + i,
    ),
  );
</script>

<arc-virtual-list bind:this={el} {overscan} {...rest}>
  {#each visible as index (index)}
    <div slot="item-{index}">{@render row(items[index], index)}</div>
  {/each}
</arc-virtual-list>
